# Test fixtures stay here; product thresholds and paths continue to come from config.
NOW = datetime(2026, 11, 2, 10)
ROOT = Path(__file__).resolve().parents[1]
APP_TIMEOUT = 60
SERVER_TIMEOUT = 60
POLL_SECONDS = 0.05
STOP_TIMEOUT = 5


def values(elements):
    """Return element text without depending on badge Markdown formatting."""
    return [element.value for element in elements]


def card_ids(app):
    """Return visible gap-card event IDs, excluding confirmations and dialog actions."""
    result = set()
    for button in app.button:
        if button.key and button.key.startswith('ww_gap_') and '_details_' in button.key:
            result.add(int(button.key.rsplit('_', 1)[1]))
    return result


# Course: U05 s2 – TestCase inheritance reuses assertions and automatic cleanup.
class DemoScenario(unittest.TestCase):
    """Follow SPEC M8 in order against one fresh temporary demo and a restored session."""

    def setUp(self):
        """Freeze the clock, reject external HTTP and capture actual ICS download contents."""
        if config.DATA_DIR == ROOT / 'data':
            raise RuntimeError('Use python -m views.check_demo to isolate all data paths first.')
        self.server = None
        self.server_log = None
        self.exports = {}
        self.http_get = api_client.requests.get
        self.http_post = api_client.requests.post
        self.build_ics = calendar_export.build_ics
        self.addCleanup(self.close_resources)
        self.start_patch(config, 'local_now', side_effect=lambda now=None: now or NOW)
        self.start_patch(api_client.requests, 'get', side_effect=self.local_get)
        self.start_patch(api_client.requests, 'post', side_effect=self.local_post)
        self.start_patch(importers, 'fetch_json', side_effect=AssertionError('External import'))
        self.start_patch(calendar_import, 'fetch_ics_text',
                         side_effect=AssertionError('External calendar'))
        self.start_patch(calendar_export, 'build_ics', side_effect=self.capture_export)
        self.training = self.start_patch(recommender, 'train_production_model',
                                         wraps=recommender.train_production_model)
        self.offline = patch.object(api_client, 'is_api_available', return_value=False)
        self.offline.start()
        self.addCleanup(self.offline.stop)

    def start_patch(self, module, name, **arguments):
        """Register mock cleanup even if an assertion or setup step fails."""
        replacement = patch.object(module, name, **arguments)
        self.addCleanup(replacement.stop)
        return replacement.start()

    def local_get(self, url, **arguments):
        """Allow only requests to the disposable local API; fail on all external traffic."""
        self.assertTrue(url.startswith(config.API_BASE_URL + '/'), url)
        self.assertEqual(urlsplit(url).hostname, '127.0.0.1')
        return self.http_get(url, **arguments)

    def local_post(self, url, **arguments):
        """Enforce the same loopback-only rule for real feedback POST requests."""
        self.assertTrue(url.startswith(config.API_BASE_URL + '/'), url)
        self.assertEqual(urlsplit(url).hostname, '127.0.0.1')
        return self.http_post(url, **arguments)

    def capture_export(self, event, *arguments, **keywords):
        """Capture the ICS text passed by the UI without replacing the export implementation."""
        text = self.build_ics(event, *arguments, **keywords)
        self.exports[event.event_id] = text
        return text

    def close_resources(self):
        """Stop only this test's process and release SQLite handles for Windows cleanup."""
        self.stop_api()
        if hasattr(self, 'connection'):
            self.connection.close()
        if config.DB_FILE.exists():
            ui_components.cached_connection().close()
        ui_components.clear_data_caches()
        ui_components.cached_connection.clear()

    def clean(self):
        """Fail on both unhandled exceptions and errors caught by the application."""
        self.assertFalse(self.app.exception, values(self.app.exception))
        self.assertFalse(self.app.error, values(self.app.error))

    def new_session(self):
        """Run the actual app shell as a new browser session against the same isolated DB."""
        self.app = AppTest.from_file(str(ROOT / 'app.py'), default_timeout=APP_TIMEOUT).run()
        self.clean()

    def details(self, event_id):
        """Requeue a dialog because AppTest reruns whole scripts rather than browser fragments."""
        self.app.session_state['ww_open_event_id'] = event_id
        self.app.run()
        self.clean()

    def test_complete_demo(self):
        """Run all automatable steps of the M8 acceptance scenario without external services."""
        self.assertFalse(config.DB_FILE.exists())
        self.onboard_and_answer()
        self.check_week_and_confirm()
        self.check_filters_and_navigation()
        self.check_rankings()
        self.check_friends()
        self.check_model()
        self.check_api_and_fallback()
        self.refresh_and_restore()

    def onboard_and_answer(self):
        """Create Alex, answer one of the two feedback prompts with four stars and defer one."""
        self.new_session()
        self.assertEqual(self.app.title[0].value, 'Welcome to WeekWise')
        self.app.button(key='ww_welcome_next').click().run()
        self.app.text_input(key='ww_onboarding_name').set_value('Alex')
        self.app.checkbox(key='ww_onboarding_sports').check()
        self.app.checkbox(key='ww_onboarding_career').check()
        self.app.checkbox(key='ww_onboarding_leisure').uncheck()
        self.assertTrue(self.app.checkbox(key='ww_demo_history').value)
        self.app.button(key='ww_focus_next').click().run()
        self.app.button(key='ww_finish_onboarding').click().run()
        self.clean()
        self.connection = database.get_connection(config.DB_FILE)
        self.user_id = database.get_current_user_id(self.connection)
        self.assertIn('130 placeholder activity series · 60 synthetic users.',
                      values(self.app.sidebar.caption))
        pending = database.get_pending_feedback(self.connection, self.user_id, NOW)
        self.assertEqual(len(pending), 2)
        self.answered, self.later = list(pending['event_id'])
        self.assertEqual(self.training.call_count, 1)
        self.app.button(key=f'ww_popup_feedback_{self.answered}_yes').click().run()
        self.app.feedback(key=f'ww_popup_feedback_{self.answered}_stars').set_value(3).run()
        self.clean()
        row = database.get_interaction(self.connection, self.user_id, self.answered)
        self.assertEqual(row['rating'], 4)
        self.assertEqual(self.training.call_count, 2)
        self.app.button(key='ww_feedback_later').click().run()
        self.clean()

    def check_week_and_confirm(self):
        """Verify capped cards, social hints, conflict removal and actual calendar export data."""
        self.assertIn('Week 45', self.app.title[0].value)
        self.assertTrue(any('Lena invited you' in text for text in values(self.app.markdown)))
        self.assertGreaterEqual(sum('friends going' in text
                                    for text in values(self.app.markdown)), 2)
        groups = {}
        for button in self.app.button:
            if button.key and button.key.startswith('ww_gap_') and '_details_' in button.key:
                group = button.key.rsplit('_details_', 1)[0]
                groups[group] = groups.get(group, 0) + 1
        self.assertTrue(groups)
        self.assertLessEqual(max(groups.values()), config.TOP_SUGGESTIONS_PER_GAP)
        self.assertTrue(any(text.startswith('Match ') and '%' in text
                            for text in values(self.app.caption)))
        invitations = friends.get_invitations(self.connection, self.user_id)['received']
        candidates = card_ids(self.app) - set(invitations['event_id'])
        events = [models.event_from_row(database.get_event_row(self.connection, event_id))
                  for event_id in sorted(card_ids(self.app))]
        self.chosen = next(event for event in events if event.event_id in candidates and any(
            other.event_id != event.event_id and event.overlap_minutes(other.start, other.end) >
            config.OVERLAP_TOLERANCE_MINUTES for other in events))
        conflicts = {event.event_id for event in events if
                     self.chosen.overlap_minutes(event.start, event.end) >
                     config.OVERLAP_TOLERANCE_MINUTES}
        self.details(self.chosen.event_id)
        self.app.session_state['ww_open_event_id'] = self.chosen.event_id
        self.app.button(key='ww_confirm_event').click().run()
        self.clean()
        self.assertFalse(conflicts & card_ids(self.app))
        self.check_export(self.chosen)

    def check_export(self, event):
        """Round-trip the downloaded ICS and inspect the generated Google compose URL."""
        self.assertIn('Download .ics', [item.label for item in self.app.get('download_button')])
        blocks, labels, recognized = calendar_import.parse_calendar(
            self.exports[event.event_id], event.start - timedelta(days=1),
            event.end + timedelta(days=1))
        self.assertIn(event.event_id, recognized)
        self.assertEqual((blocks[0].start, blocks[0].end), (event.start, event.end))
        google = next(item for item in self.app.get('link_button')
                      if item.label == 'Add to Google Calendar')
        url = urlsplit(google.proto.url)
        self.assertEqual(url.hostname, 'calendar.google.com')
        self.assertEqual(parse_qs(url.query)['text'], [event.title])

    def check_filters_and_navigation(self):
        """Use Racket sports, public source links and the bounded week-navigation widgets."""
        self.app.run()
        self.app.multiselect(key='ww_filter_many_sports').set_value(['sports_racket']).run()
        self.clean()
        ids = card_ids(self.app)
        self.assertTrue(ids)
        for event_id in ids:
            row = database.get_event_row(self.connection, event_id)
            self.assertEqual(row['bundle_key'], 'sports_racket')
        self.assertTrue(self.app.get('link_button'))
        self.app.button(key='ww_clear_filters').click().run()
        monday = self.app.session_state['ww_week_start']
        self.app.button(key='ww_next_week').click().run()
        self.assertEqual(self.app.session_state['ww_week_start'], monday + timedelta(days=7))
        self.app.button(key='ww_previous_week').click().run()
        self.assertEqual(self.app.session_state['ww_week_start'], monday)
        self.app.button(key='ww_today').click().run()
        self.clean()
        self.assertEqual(self.app.session_state['ww_week_start'], NOW.date())
        beyond = [item for item in self.app.expander if item.label.startswith('Beyond')]
        self.assertTrue(beyond)
        self.assertTrue(any(button.key.startswith('ww_beyond_') for button in beyond[0].button))

    def check_rankings(self):
        """Require nonempty Career rankings and charts for both the local and aggregate scope."""
        self.app.switch_page('views/rankings.py').run()
        self.app.selectbox(key='ww_ranking_category').select('Career').run()
        self.clean()
        self.assertEqual(values(self.app.subheader)[:2], ['You', 'All users'])
        for table in self.app.dataframe[:2]:
            self.assertFalse(table.value.empty)
        self.assertEqual(len(self.app.get('image')), 3)

    def check_friends(self):
        """Add Luca, invite Lena with a simulated response, and accept Noah's invitation."""
        self.app.switch_page('views/friends.py').run()
        self.app.text_input(key='ww_friend_code_input').set_value('LUCA26')
        self.app.button(key='ww_add_friend').click().run()
        self.clean()
        people = friends.get_friends_df(self.connection, self.user_id)
        self.assertEqual(len(people), 4)
        lena = int(people.loc[people['friend_code'] == 'LENA26'].index[0])
        self.details(self.chosen.event_id)
        key = f'ww_invite_friends_{self.chosen.event_id}'
        self.app.multiselect(key=key).set_value([lena])
        self.details(self.chosen.event_id)
        self.app.session_state['ww_open_event_id'] = self.chosen.event_id
        self.app.button(key=f'ww_send_invites_{self.chosen.event_id}').click().run()
        self.clean()
        sent = friends.get_invitations(self.connection, self.user_id)['sent']
        self.assertEqual(len(sent), 1)
        self.assertEqual(int(sent.iloc[0]['is_simulated']), 1)
        self.assertIn(sent.iloc[0]['status'], ('accepted', 'declined'))
        self.assertTrue(any('(simulated)' in text for text in values(self.app.caption)))
        self.app.run()
        received = friends.get_invitations(self.connection, self.user_id)['received']
        noah = received.loc[received['sender_name'] == 'Noah'].iloc[0]
        self.app.button(key=f'ww_received_{noah.name}_accept').click().run()
        self.clean()
        event_id = int(noah['event_id'])
        self.assertEqual(database.get_interaction(self.connection, self.user_id, event_id)
                         ['status'], 'confirmed')
        self.check_export(models.event_from_row(database.get_event_row(self.connection, event_id)))

    def check_model(self):
        """Open the real evaluation tab and require ten variants, held-out metrics and charts."""
        self.app.switch_page('views/settings.py').run()
        # AppTest has no tab-select method; tracked tabs store their label in session state.
        self.app.session_state['ww_settings_tab'] = 'About the model'
        self.app.run()
        self.clean()
        comparison = next(table.value for table in self.app.dataframe
                          if 'val_f1' in table.value.columns)
        self.assertEqual(len(comparison), 10)
        self.assertIn('val_f1', comparison)
        self.assertGreaterEqual(len(self.app.metric), 7)
        self.assertGreaterEqual(len(self.app.get('image')), 2)
        self.assertTrue(any('precision' in text for text in values(self.app.code)))

    def start_api(self):
        """Launch the production API factory as a separate bounded loopback-only process."""
        with socket.socket() as listener:
            listener.bind(('127.0.0.1', 0))
            port = listener.getsockname()[1]
        config.API_BASE_URL = f'http://127.0.0.1:{port}'
        environment = os.environ.copy()
        environment['NO_PROXY'] = environment.get('NO_PROXY', '') + ',127.0.0.1,localhost'
        environment['no_proxy'] = environment['NO_PROXY']
        command = [sys.executable, '-m', 'views.check_demo', '--api', str(config.DB_FILE),
                   str(port), NOW.isoformat()]
        # A subprocess is test infrastructure only; the application has no background scheduler.
        self.server_log = (config.DATA_DIR / 'acceptance-api.log').open('w+b')
        self.server = subprocess.Popen(command, cwd=ROOT, env=environment,
                                       stdout=self.server_log, stderr=subprocess.STDOUT)
        deadline = time.monotonic() + SERVER_TIMEOUT
        while time.monotonic() < deadline:
            if self.server.poll() is not None:
                self.fail('Local API exited before becoming healthy: ' + self.api_log())
            if api_client.is_api_available():
                return
            time.sleep(POLL_SECONDS)
        self.fail('Local API did not become healthy within the startup timeout: ' + self.api_log())

    def api_log(self):
        """Read disposable API diagnostics when startup fails instead of discarding the cause."""
        self.server_log.seek(0)
        return self.server_log.read().decode('utf-8', errors='replace')

    def stop_api(self):
        """Terminate and reap only the API child created by this scenario."""
        if self.server is not None:
            self.server.terminate()
            try:
                self.server.wait(timeout=STOP_TIMEOUT)
            except subprocess.TimeoutExpired:
                self.server.kill()
                self.server.wait(timeout=STOP_TIMEOUT)
            self.server = None
        if self.server_log is not None:
            self.server_log.close()
            self.server_log = None

    def check_api_and_fallback(self):
        """Exercise real HTTP GET/POST and immediate SQLite fallback after server shutdown."""
        self.offline.stop()
        self.start_api()
        # Clear the 30-second health cache instead of making CI wait for its ordinary expiry.
        ui_components.cached_api_available.clear()
        ui_components.cached_events.clear()
        self.app.switch_page('views/week.py').run()
        self.clean()
        self.assertIn(config.API_STATUS_LABELS['api'], values(self.app.sidebar.caption))
        self.details(self.chosen.event_id)
        self.app.session_state['ww_open_event_id'] = self.chosen.event_id
        self.app.button(key='ww_cancel_event').click().run()
        self.clean()
        self.app.session_state['ww_open_event_id'] = self.chosen.event_id
        self.app.button(key='ww_confirm_event').click().run()
        self.clean()
        self.assertEqual(self.app.session_state['ww_event_data_origin'], 'api')
        self.stop_api()
        self.details(self.chosen.event_id)
        self.app.run()
        self.clean()
        self.assertIn(config.API_STATUS_LABELS['database'], values(self.app.sidebar.caption))
        self.assertEqual(self.app.session_state['ww_event_data_origin'], 'database')

    def refresh_and_restore(self):
        """Refresh all three sources, retain feedback and reopen only the deferred popup row."""
        before = len(database.get_import_log_df(self.connection))
        rating_key = database.get_rating_cache_key(self.connection)
        self.app.switch_page('views/settings.py').run()
        self.app.session_state['ww_settings_tab'] = 'Data sources'
        self.app.run()
        self.app.button(key='ww_refresh_sources').click().run()
        self.clean()
        self.assertEqual(len(database.get_import_log_df(self.connection)), before + 3)
        self.assertEqual(database.get_rating_cache_key(self.connection), rating_key)
        self.new_session()
        self.assertTrue(self.app.session_state['ww_feedback_open'])
        self.assertEqual(self.app.session_state['ww_feedback_ids'], [self.later])
        profile = database.get_user_profile(self.connection, self.user_id)
        self.assertEqual(profile.directions, {'sports', 'career'})
        self.assertEqual(profile.display_name, 'Alex')
        self.assertEqual(len(database.get_synthetic_users_df(self.connection)), 60)
        self.assertNotIn('Microeconomics', '\n'.join(self.connection.iterdump()))
